function norm(s){return s.replace(/\r\n/g,"\n")}
function shaText(s){return crypto.createHash("sha256").update(norm(s)).digest("hex")}
function shaBuf(b){return crypto.createHash("sha256").update(b).digest("hex")}
function git(wt,args){return cp.execFileSync("git",["-C",wt,...args],{encoding:"utf8"}).trimEnd()}
function status(wt){const s=git(wt,["status","--porcelain=v1","--untracked-files=all"]);return s?s.split(/\r?\n/).filter(Boolean).map(x=>({line:x,file:x.slice(3).trim().replace(/\\/g,"/")})):[]}
function assertScope(wt){
 const st=status(wt); for(const x of st)if(!SCOPE.has(x.file))throw new Error(`STOP: unexpected file in active TAYQAN worktree: ${x.file}`);
 const files=new Set(st.map(x=>x.file)); for(const f of SCOPE)if(!files.has(f))throw new Error(`STOP: expected TAYQAN file missing from worktree scope: ${f}`);
}
function stateMatches(wt,map){return Object.entries(map).every(([rel,h])=>{const f=path.join(wt,rel);return fs.existsSync(f)&&shaText(fs.readFileSync(f,"utf8"))===h})}
function writeEol(file,text,original){const eol=original.includes("\r\n")?"\r\n":"\n";fs.writeFileSync(file,norm(text).replace(/\n/g,eol),"utf8")}
